import { TreeView, type TreeNode, type TreeViewMoveDetail } from '@absoluteui/components/tree-view';

const nodes: TreeNode[] = [
  { id: 'policies', label: 'Policies', children: [
    { id: 'leave', label: 'Leave policy.pdf', icon: 'file' },
    { id: 'travel', label: 'Travel policy.pdf', icon: 'file' },
  ] },
  { id: 'archive', label: 'Archive', hasChildren: true },
];
const host = document.createElement('div');
document.body.append(host);
const tree = TreeView.create(host, {
  label: 'Documents',
  nodes,
  selection: 'single',
  expanded: ['policies'],
  draggable: true,
  renamable: true,
  // Files (nodes with the file icon) cannot contain other nodes.
  canDrop: (_source, target, position) => position !== 'inside' || target?.icon !== 'file',
  loadChildren: async (node, { signal }) => {
    const res = await fetch(`/api/folders/${encodeURIComponent(node.id)}`, { signal });
    return (await res.json()) as TreeNode[];
  },
});
host.addEventListener('aui-move', (event) => {
  const { id, parentId, index } = (event as CustomEvent<TreeViewMoveDetail>).detail;
  host.dataset.lastMove = `${id} -> ${parentId ?? 'root'} at ${String(index)}`;
});
void tree.expand('archive');

import { TreeView, type TreeViewChangeDetail } from '@absoluteui/components/tree-view';

const host = document.createElement('div');
document.body.append(host);
const tree = TreeView.create(host, {
  label: 'Locations',
  checkboxes: true,
  checked: ['berlin'],
  expanded: ['emea'],
  nodes: [
    { id: 'emea', label: 'Europe', children: [
      { id: 'berlin', label: 'Berlin' },
      { id: 'paris', label: 'Paris' },
    ] },
    { id: 'apac', label: 'Asia Pacific', children: [{ id: 'sydney', label: 'Sydney' }] },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { checked, indeterminate } = (event as CustomEvent<TreeViewChangeDetail>).detail;
  host.dataset.checked = `${String(checked.length)} checked, ${String(indeterminate.length)} mixed`;
});
tree.update({ filter: 'par' });
